import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import java.util.*;import java.util.zip.*;
public class Inspect implements Opcodes{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static ClassNode read(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}
 static List<MethodInsnNode> calls(MethodNode m){List<MethodInsnNode> out=new ArrayList<>();for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n)out.add(n);return out;}
 public static void main(String[]a)throws Exception{try(ZipFile remains=new ZipFile(a[0]);ZipFile hordes=new ZipFile(a[1]);ZipFile quiet=new ZipFile(a[2]);ZipFile turret=new ZipFile(a[3])){
  ClassNode bridge=read(remains,"dev/zomboid/remains/CorpseBridge35");List<MethodInsnNode> body=calls(bridge.methods.stream().filter(m->m.name.equals("body")).findFirst().orElseThrow());ok(body.getLast().owner.equals("dev/zomboid/remains/LootFinish15"),"final rules run after original body generation and scrap bridge");ClassNode corpse=read(remains,"dev/zomboid/remains/ZombieRemainsLoot$Corpse");ok(corpse.fields.stream().anyMatch(f->f.name.equals("lootFinal15")&&f.desc.equals("Z")),"finalization persists per corpse");ok(corpse.fields.stream().anyMatch(f->f.name.equals("lootOwned15")&&f.desc.equals("Z")),"owned cargo has separate hidden marker");
  ClassNode loot=read(quiet,"dev/zomboid/scavenging/Loot");MethodNode bonus=loot.methods.stream().filter(m->m.name.equals("bonus")).findFirst().orElseThrow();ok(calls(bonus).stream().filter(n->n.owner.equals("dev/zomboid/scavenging/FinalLoot17")&&n.name.equals("after")).count()==2,"bonus returns each run postpass");MethodNode insert=loot.methods.stream().filter(m->m.name.equals("insert")).findFirst().orElseThrow();ok(calls(insert).getFirst().name.equals("prepare"),"filter before stack insertion, avoids temporary tool explosion");
  ClassNode t=read(turret,"com/entropy/tacz_turrets/turret/TurretEntity");ok(t.fields.stream().anyMatch(f->f.name.equals("ZH_TIER4")&&f.desc.endsWith("EntityDataAccessor;")),"tier uses synchronized entity data");for(String method:List.of("defineSynchedData","addAdditionalSaveData","readAdditionalSaveData","getRange","syncAttributes")){ok(calls(t.methods.stream().filter(m->m.name.equals(method)).findFirst().orElseThrow()).stream().anyMatch(n->n.owner.equals("dev/zomboid/turretpower/Tier4")),"native bridge "+method);}
  int pickups=0;for(MethodNode m:t.methods)pickups+=calls(m).stream().filter(n->n.owner.equals("dev/zomboid/turretpower/Tier4")&&n.name.equals("item")).count();ok(pickups==3,"all three pickup/pick-block/drop-on-placement paths retain tier");
  ClassNode item=read(turret,"com/entropy/tacz_turrets/item/TurretItem");List<MethodInsnNode> place=calls(item.methods.stream().filter(m->m.name.equals("useOn")).findFirst().orElseThrow());int tierIndex=-1,spawnIndex=-1;for(int i=0;i<place.size();i++){if(place.get(i).name.equals("place"))tierIndex=i;if(place.get(i).name.equals("addFreshEntity"))spawnIndex=i;}ok(tierIndex>=0&&tierIndex<spawnIndex,"tier assigned before entity spawn");
  ClassNode model=read(turret,"com/entropy/tacz_turrets/client/model/TurretModel");for(String method:List.of("getModelResource","getTextureResource"))ok(model.methods.stream().filter(m->m.name.equals(method)).anyMatch(m->calls(m).stream().anyMatch(n->n.owner.equals("dev/zomboid/turretpower/Tier4"))),"matching native model and texture selection "+method);
 }System.out.println("NATIVE_PIPELINE_HOOK_CHECKS="+checks);}
}
